package tv.nova.player;

import android.app.*;
import android.os.*;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import android.text.*;
import android.content.*;
import android.net.Uri;
import org.json.*;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import androidx.media3.common.*;
import androidx.media3.exoplayer.ExoPlayer;
import androidx.media3.ui.PlayerView;

public class MainActivity extends Activity {
  final int bg=Color.rgb(9,15,29), panel=Color.rgb(19,29,49), accent=Color.rgb(61,220,190);
  final ExecutorService io=Executors.newSingleThreadExecutor();
  final ArrayList<Channel> channels=new ArrayList<>(), shown=new ArrayList<>();
  SharedPreferences prefs; LinearLayout root, list; EditText address,user,pass,mac,search; Spinner mode; TextView status,title,count;
  ExoPlayer player; PlayerView playerView; boolean loading=false;
  static class Channel { String name,url,group,logo; Channel(String n,String u,String g,String l){name=n;url=u;group=g;logo=l;} }
  @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);prefs=getSharedPreferences("nova",0);player=new ExoPlayer.Builder(this).build();restore();home();}
  int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
  TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
  GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
  LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(16),dp(12),dp(16),dp(12));return l;}
  Button btn(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackground(shape(panel,14));b.setOnClickListener(v->r.run());return b;}
  EditText field(String hint,String key){EditText e=new EditText(this);e.setSingleLine(true);e.setTextColor(Color.WHITE);e.setHintTextColor(0xff9ba9bc);e.setHint(hint);e.setBackground(shape(panel,12));e.setPadding(dp(12),0,dp(12),0);e.setText(prefs.getString(key,""));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.bottomMargin=dp(8);root.addView(e,p);return e;}
  void base(String heading){root=column();root.setBackgroundColor(bg);ScrollView sc=new ScrollView(this);sc.addView(root);setContentView(sc);TextView brand=text("N O V A   /   IPTV",13,accent);root.addView(brand);TextView h=text(heading,28,Color.WHITE);h.setPadding(0,dp(12),0,dp(12));root.addView(h);}
  void home(){base("شاهد بطريقتك");TextView sub=text("مشغّل IPTV مستقل • بسيط • سريع",15,0xffaebbd0);root.addView(sub);LinearLayout.LayoutParams gap=new LinearLayout.LayoutParams(-1,dp(14));root.addView(new View(this),gap);root.addView(btn("＋  إضافة مصدر IPTV",()->sources()),new LinearLayout.LayoutParams(-1,dp(54)));root.addView(btn("▶  القنوات المباشرة",()->live()),new LinearLayout.LayoutParams(-1,dp(54)));root.addView(btn("⚙  الإعدادات",()->settings()),new LinearLayout.LayoutParams(-1,dp(54)));TextView note=text(channels.size()+" قناة محفوظة على هذا الجهاز",14,accent);note.setPadding(0,dp(20),0,0);root.addView(note);}
  void sources(){base("إضافة مصدر");TextView tip=text("استخدم بيانات مصدر تملك حق الوصول إليه.",13,0xffaebbd0);root.addView(tip);mode=new Spinner(this);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"M3U / M3U8","Xtream Codes","Stalker Portal"});mode.setAdapter(a);mode.setSelection(prefs.getInt("mode",0));root.addView(mode,new LinearLayout.LayoutParams(-1,dp(48)));address=field("رابط قائمة M3U أو عنوان الخادم","address");user=field("اسم المستخدم (Xtream)","user");pass=field("كلمة المرور (Xtream)","pass");pass.setInputType(129);mac=field("MAC address (Stalker)","mac");root.addView(btn("حفظ وتحميل القنوات",()->load()),new LinearLayout.LayoutParams(-1,dp(52)));root.addView(btn("رجوع",()->home()),new LinearLayout.LayoutParams(-1,dp(48)));status=text("اختر نوع المصدر ثم أدخل البيانات.",14,accent);root.addView(status);}
  String request(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent","NOVA-IPTV/1.0");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}finally{c.disconnect();}}
  String enc(String s)throws Exception{return java.net.URLEncoder.encode(s,"UTF-8");}
  void load(){if(loading)return;int m=mode.getSelectedItemPosition();String addr=address.getText().toString().trim(),u=user.getText().toString().trim(),p=pass.getText().toString(),mc=mac.getText().toString().trim();if(addr.isEmpty()){status.setText("أدخل عنوان المصدر أولاً.");return;}loading=true;status.setText("جارٍ الاتصال بالمصدر…");io.execute(()->{try{ArrayList<Channel> got;if(m==0)got=parseM3u(addr);else if(m==1)got=parseXtream(addr,u,p);else got=parseStalker(addr,mc);runOnUiThread(()->{loading=false;channels.clear();channels.addAll(got);prefs.edit().putInt("mode",m).putString("address",addr).putString("user",u).putString("pass",p).putString("mac",mc).apply();save();status.setText("تم تحميل "+got.size()+" قناة");live();});}catch(Exception e){runOnUiThread(()->{loading=false;status.setText("تعذر التحميل: "+e.getMessage());});}});}
  ArrayList<Channel> parseM3u(String url)throws Exception{String body=request(url);ArrayList<Channel> out=new ArrayList<>();String name="قناة",group="",logo="";for(String raw:body.replace("\ufeff","").split("\\r?\\n")){String l=raw.trim();if(l.startsWith("#EXTINF")){int comma=l.lastIndexOf(',');name=comma>=0?l.substring(comma+1).trim():attr(l,"tvg-name");group=attr(l,"group-title");logo=attr(l,"tvg-logo");}else if(l.startsWith("#EXTGRP:"))group=l.substring(8).trim();else if(!l.isEmpty()&&!l.startsWith("#")){try{if(!l.matches("(?i)^[a-z][a-z0-9+.-]*://.*"))l=new URL(new URL(url),l).toString();}catch(Exception ignored){}if(l.matches("(?i)^(https?|rtsp|rtmp|udp)://.*"))out.add(new Channel(name,l,group,logo));name="قناة";group="";logo="";}}if(out.isEmpty())throw new Exception("لم نعثر على روابط M3U صالحة");return out;}
  String attr(String line,String key){java.util.regex.Matcher m=java.util.regex.Pattern.compile(key+"=\"([^\"]*)\"").matcher(line);return m.find()?m.group(1):"";}
  ArrayList<Channel> parseXtream(String base,String u,String p)throws Exception{if(u.isEmpty()||p.isEmpty())throw new Exception("أدخل اسم المستخدم وكلمة المرور");base=base.replaceAll("/+$","");String json=request(base+"/player_api.php?username="+enc(u)+"&password="+enc(p)+"&action=get_live_streams");JSONArray a=new JSONArray(json);ArrayList<Channel> out=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String id=o.optString("stream_id");String ext=o.optString("container_extension","ts");String stream=base+"/live/"+enc(u)+"/"+enc(p)+"/"+id+"."+ext;out.add(new Channel(o.optString("name","قناة"),stream,o.optString("category_name","مباشر"),o.optString("stream_icon","")));}if(out.isEmpty())throw new Exception("الخادم لم يُرجع قنوات مباشرة");return out;}
  ArrayList<Channel> parseStalker(String portal,String macAddr)throws Exception{if(macAddr.isEmpty())throw new Exception("أدخل MAC المخصص للبوابة");String p=portal.replaceAll("/+$","");String token=request(p+"/server/load.php?type=stb&action=handshake&token=&JsHttpRequest=1-xml");JSONObject j=new JSONObject(token);JSONObject data=j.optJSONObject("js");String tok=data==null?"":data.optString("token");if(tok.isEmpty())throw new Exception("لم تنجح مصافحة Stalker؛ قد تتطلب البوابة headers أو مصادقة إضافية");String url=p+"/server/load.php?type=itv&action=get_all_channels&JsHttpRequest=1-xml";HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestProperty("Authorization","Bearer "+tok);c.setRequestProperty("Cookie","mac="+macAddr+"; stb_lang=en; timezone=GMT");c.setConnectTimeout(15000);c.setReadTimeout(20000);String body;try(InputStream in=c.getInputStream()){body=new String(in.readAllBytes(),StandardCharsets.UTF_8);}finally{c.disconnect();}JSONObject all=new JSONObject(body);JSONObject js=all.optJSONObject("js");JSONArray arr=js==null?new JSONArray():js.optJSONArray("data");ArrayList<Channel> out=new ArrayList<>();if(arr!=null)for(int i=0;i<arr.length();i++){JSONObject o=arr.getJSONObject(i);String id=o.optString("id");out.add(new Channel(o.optString("name","قناة"),p+"/server/load.php?type=itv&action=create_link&cmd="+enc("ffmpeg http://localhost/ch/"+id)+"&JsHttpRequest=1-xml",o.optString("tv_genre_title","Stalker"),o.optString("logo","")));}if(out.isEmpty())throw new Exception("لم تُرجع بوابة Stalker قنوات قابلة للعرض؛ تختلف API بين البوابات");return out;}
  void save(){try{JSONArray a=new JSONArray();for(Channel c:channels){JSONObject o=new JSONObject();o.put("n",c.name);o.put("u",c.url);o.put("g",c.group);o.put("l",c.logo);a.put(o);}try(FileOutputStream f=openFileOutput("nova.json",0)){f.write(a.toString().getBytes(StandardCharsets.UTF_8));}}catch(Exception ignored){}}
  void restore(){try(InputStream in=openFileInput("nova.json")){JSONArray a=new JSONArray(new String(in.readAllBytes(),StandardCharsets.UTF_8));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);channels.add(new Channel(o.optString("n"),o.optString("u"),o.optString("g"),o.optString("l")));}}catch(Exception ignored){}}
  void live(){base("البث المباشر");LinearLayout playerBox=column();playerBox.setBackground(shape(panel,16));playerView=new PlayerView(this);playerView.setPlayer(player);playerView.setUseController(true);playerBox.addView(playerView,new LinearLayout.LayoutParams(-1,dp(220)));root.addView(playerBox,new LinearLayout.LayoutParams(-1,dp(250)));search=new EditText(this);search.setSingleLine(true);search.setHint("ابحث عن قناة…");search.setTextColor(Color.WHITE);search.setHintTextColor(0xff9ba9bc);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){renderList();}public void afterTextChanged(Editable e){}});root.addView(search,new LinearLayout.LayoutParams(-1,dp(48)));count=text("",14,accent);root.addView(count);list=new LinearLayout(this);list.setOrientation(1);root.addView(list);renderList();root.addView(btn("＋ إضافة مصدر",()->sources()));root.addView(btn("الرئيسية",()->home()));}
  void renderList(){if(list==null)return;list.removeAllViews();String q=search==null?"":search.getText().toString().toLowerCase(Locale.ROOT);int n=0;for(Channel c:channels){if(!c.name.toLowerCase(Locale.ROOT).contains(q)&&!c.group.toLowerCase(Locale.ROOT).contains(q))continue;n++;TextView row=text("▶   "+c.name+"\n      "+c.group,15,Color.WHITE);row.setPadding(dp(12),dp(12),dp(12),dp(12));row.setBackground(shape(panel,12));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(62));lp.bottomMargin=dp(5);list.addView(row,lp);row.setFocusable(true);row.setOnClickListener(v->{title=null;try{player.setMediaItem(MediaItem.fromUri(Uri.parse(c.url)));player.prepare();player.play();}catch(Exception e){Toast.makeText(this,"تعذر تشغيل القناة",Toast.LENGTH_SHORT).show();}});}if(count!=null)count.setText(n+" قناة");}
  void settings(){base("الإعدادات");root.addView(text("NOVA IPTV • الإصدار 1.0",15,accent));root.addView(text("يتم حفظ قائمة القنوات محلياً على الجهاز.",13,0xffaebbd0));root.addView(btn("مسح القنوات المحفوظة",()->{channels.clear();save();home();}));root.addView(btn("العودة",()->home()));}
  @Override public void onBackPressed(){home();}
  @Override protected void onDestroy(){super.onDestroy();if(player!=null)player.release();io.shutdownNow();}
}
